    pub fn set_option(&self) {
    }

    // Java: boolean gotEnoughData()
    pub fn got_enough_data(&self) -> bool {
        // Java: return this.totalRel > 100;
        self.total_rel > ENOUGH_REL_THRESHOLD
    }

